-- OGO Miralinks cleanup: strip external a tags, preserving text and all other HTML.
-- Approved article list: visible sheets only. anons and post dates are untouched.
-- Exact-content hashes prevent overwriting edits made since the CSV export.
-- Backup table: `ogo2023_ogo`.`wp_ogo_miralinks_backup_de0a5dfdeb16` (kept for rollback).
-- Backups are committed BEFORE any article is updated. Safe to re-run.
CREATE TABLE IF NOT EXISTS `ogo2023_ogo`.`wp_ogo_miralinks_backup_de0a5dfdeb16` (
  post_id bigint unsigned NOT NULL PRIMARY KEY,
  before_content LONGBLOB NOT NULL,
  before_sha256 binary(64) NOT NULL,
  after_sha256 binary(64) NOT NULL,
  post_status varbinary(20) NOT NULL,
  post_date datetime NOT NULL,
  saved_gmt datetime NOT NULL
) ENGINE=InnoDB;

